SELECT ar.repo_id, ar.repo_name, ar.repo_type, ar.description, ar.owner_user_id, ar.visibility, ar.created_at, COALESCE( (SELECT MAX(published_at) FROM public.artifact_commit ac WHERE ac.repo_id = ar.repo_id AND ac.commit_status = 'PUBLISHED'), ar.updated_at ) as updated_at FROM public.artifact_repo ar LEFT JOIN public.fwd_user u ON ar.owner_user_id = u.user_id
AND ar.visibility = #{query.visibilityOrNull}
AND ar.repo_type = #{query.repoTypeOrNull}
AND ar.owner_user_id = #{query.ownerUserIdOrNull}
AND u.user_name = #{query.ownerUserNameOrNull}
AND (ar.repo_name ILIKE CONCAT('%', #{query.searchKeyword}, '%') OR ar.description ILIKE CONCAT('%', #{query.searchKeyword}, '%'))
ORDER BY ${query.sortByOrDefault} ${query.sortOrderOrDefault} LIMIT #{query.limit} OFFSET #{query.offset}

SELECT COUNT(*)
FROM public.artifact_repo ar
LEFT JOIN public.fwd_user u ON ar.owner_user_id = u.user_id


        AND ar.visibility = #{query.visibilityOrNull}


        AND ar.repo_type = #{query.repoTypeOrNull}


