        AND u.user_name = #{query.ownerUserNameOrNull}


        AND (ar.repo_name ILIKE CONCAT('%', #{query.searchKeyword}, '%')
             OR ar.description ILIKE CONCAT('%', #{query.searchKeyword}, '%'))
